class Solution:
    def longestWord(self, words: list[str]) -> str:
        word_set = set(words)
        words.sort(key=lambda w: (-len(w), w))
        for word in words:
            if all(word[:i] in word_set for i in range(1, len(word) + 1)):
                return word
        return ""

